    from collections import Counter
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Every single isolated non-background pixel marks one wall.  Put a
    # colored 2x2 block immediately beyond that wall, outside the shape.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == 0:
                continue
            isolated = True
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == dc == 0:
                        continue
                    a, b = r + dr, c + dc
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == color:
                        isolated = False
            if not isolated:
                continue
            candidates = []
            for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                a, b = r, c
                run = 0
                last = None
                while True:
                    a += dr
                    b += dc
                    run += 1
                    if not (0 <= a < h and 0 <= b < w):
                        break
                    if grid[a][b] != 0:
                        break
                    last = (a, b)
                if last is not None:
                    # A wall run cannot pass through another marker and has
                    # at most two zero cells in these tasks.
                    if run <= 3:
                        candidates.append((run, dr, dc, last))
            if not candidates:
                continue
            _, dr, dc, (a, b) = min(candidates)
            for x, y in ((a + dr, b), (a, b + dc), (a + dr, b + dc)):
                if 0 <= x < h and 0 <= y < w and g[x][y] == bg:
                    g[x][y] = color
    return g
